/* BT <-> Terminal. Shown in Bluetooth LE status, but not currently used: the
 * firmware always follows the Enable BT setting instead.
 * Wire: w\b\b\t
 */
int owlv_wireless_bluetooth_le_ble_settings_b_t_terminal(int session);

/* BT Advert Name. Set the name the device advertises over Bluetooth LE.
 * Wire: w\b\b\a
 */
int owlv_wireless_bluetooth_le_ble_settings_b_t_advert_name(int session,
                                                            const char* value);

/* Stream IR. Enables or disables streaming of received IR codes to the
 * host..
 * Wire: w\i\o
 */
int owlv_wireless_ir_enable_ir_stream(int session, int enable);

/* Send IR. Transmits a 4-byte IR code..
 * Wire: w\i\a
 */
int owlv_wireless_ir_send_ir_data(int session, int ir_code);

/* IR Self Test. Transmits one frame per supported protocol and checks that
 * the on-board receiver decodes each one back. Takes a few seconds and emits
 * infrared..
 * Wire: w\i\t
 */
int owlv_wireless_ir_ir_self_test(int session);

/* List IR Dir. Lists the directories and .ir files on the SD card,
 * directories first. Empty path lists \ir\..
 * Wire: w\i\l
 */
int owlv_wireless_ir_ir_list_dir(int session, const char* path);

/* List IR Buttons. Lists the buttons in one Flipper .ir file with the index
 * each one is sent by. Malformed entries are counted as skipped, not
 * listed..
 * Wire: w\i\b
 */
int owlv_wireless_ir_ir_list_buttons(int session, const char* path);

/* Send IR Button. Transmits one button from a .ir file, repeated by the IR
 * Repeat setting. Emits infrared..
 * Wire: w\i\s
 */
int owlv_wireless_ir_ir_send_button(int session, int index, const char* path);

/* Save IR Capture. Appends the last received signal to \ir\learned.ir under
 * this name, decoded when the protocol was recognised and as raw timings
 * when it was not..
 * Wire: w\i\c
 */
int owlv_wireless_ir_ir_save_capture(int session, const char* name);

/* IR Status. Reports the IR engine's carrier, repeat count, capture overruns
 * and whether the \ir\ tree exists on the card..
 * Wire: w\i\i
 */
int owlv_wireless_ir_ir_status(int session);

/* IR Carrier. Default transmit carrier frequency. Only these four are legal;
 * a .ir raw entry with its own frequency line overrides this for that
 * entry..
 * Wire: w\i\f
 */
int owlv_wireless_ir_i_r_carrier(int session, int value);

/* IR Repeat. How many times Send IR Button transmits each frame, 1 to 5,
 * with a 40 ms gap between repeats..
 * Wire: w\i\r
 */
int owlv_wireless_ir_i_r_repeat(int session, int value);

/* Configure. LoRa modem params:.
 * Wire: w\l\c
 */
int owlv_wireless_lo_ra_configure(int session, int freq_hz, int sf,
                                  int bw_enc, int cr, int power, int preamble,
                                  unsigned char sync);

/* Send. Transmits a LoRa packet.
 * Wire: w\l\s
 */
int owlv_wireless_lo_ra_send_payload(int session, const unsigned char* data,
                                     int data_len);

/* RX Enable. RX control:.
 * Wire: w\l\r
 */
int owlv_wireless_lo_ra_rx_enable(int session, int mode);

/* Status. WIO-E5 bridge status (a 'lora' STATUS event):.
 * Wire: w\l\t
 */
int owlv_wireless_lo_ra_status(int session);

/* Raw Frame. Sends a raw framed command to the bridge (advanced).
 * Wire: w\l\f
 */
int owlv_wireless_lo_ra_raw_frame(int session, unsigned char cmd_,
                                  const unsigned char* payload,
                                  int payload_len);

/* Select Circuit. Claims the sub-GHz front end for this client and holds it
 * until Release..
 * Wire: w\r\s
 */
int owlv_wireless_radio_select_circuit(int session, int band);

/* Release Circuit. Ends this client's circuit hold and hands the antenna
 * back to LoRa..
 * Wire: w\r\e
 */
int owlv_wireless_radio_release_circuit(int session);

/* State. Reads the mux and radio state back, in this order:.
 * Wire: w\r\t
 */
int owlv_wireless_radio_read_state(int session, int* owner, int* holder,
                                   int* band, int* want_v1, int* want_v2,
                                   int* have_valid, int* have_v1,
                                   int* have_v2, int* lora_paused,
                                   int* freq_hz, int* active, int* status,
                                   unsigned char* version);

/* Band. Forces the matched antenna path now: 1 low, 2 mid, 3 high..
 * Wire: w\r\b
 */
int owlv_wireless_radio_select_band(int session, int band);

/* Comm Check. Reads the CC1101 version register and returns it..
 * Wire: w\r\c
 */
int owlv_wireless_radio_comm_check(int session, unsigned char* version);

/* Frequency. Tunes the CC1101 and selects the matched antenna path for that
 * band..
 * Wire: w\r\f
 */
int owlv_wireless_radio_set_frequency(int session, int freq_hz, int* band);

/* RSSI. Samples received signal strength once, in dBm..
 * Wire: w\r\i
 */
int owlv_wireless_radio_read_rssi(int session, int* rssi);

/* Carrier. Keys or unkeys an unmodulated carrier at the current frequency..
 * Wire: w\r\o
 */
int owlv_wireless_radio_carrier(int session, int on);

/* RX Enable. Puts the CC1101 into continuous receive, or back to idle..
 * Wire: w\r\r
 */
int owlv_wireless_radio_rx_enable(int session, int on);

/* Idle. Returns the CC1101 to idle from receive, transmit or carrier..
 * Wire: w\r\w
 */
int owlv_wireless_radio_idle(int session);

/* Packet Send. Transmits one GFSK packet through the CC1101 packet engine..
 * Wire: w\r\x
 */
int owlv_wireless_radio_packet_send(int session, int freq_hz,
                                    const unsigned char* data, int data_len);

/* Packet RX. Opens or closes the GFSK packet receiver at the given
 * frequency..
 * Wire: w\r\y
 */
int owlv_wireless_radio_packet_rx(int session, int on, int freq_hz);

/* Packet Read. Reads the last received GFSK packet: RSSI in dBm, a sequence
 * counter that.
 * Wire: w\r\k
 */
int owlv_wireless_radio_packet_read(int session, int* rssi, int* seq,
                                    unsigned char* data, int data_cap,
                                    int* data_len);

/* Capture Start. Arms a raw pulse-duration capture at the given frequency..
 * Wire: w\r\g
 */
int owlv_wireless_radio_capture_start(int session, int freq_hz, int preset);

/* Capture Stop. Ends a capture and returns how many pulse durations it
 * recorded..
 * Wire: w\r\j
 */
int owlv_wireless_radio_capture_stop(int session, int* durations);

/* Replay. Re-transmits the last capture out the transmit path..
 * Wire: w\r\p
 */
int owlv_wireless_radio_replay(int session);

/* Analyzer. Starts or stops the background frequency-analyzer sweep..
 * Wire: w\r\a
 */
int owlv_wireless_radio_analyzer(int session, int on);

/* Spectrum. Reads the analyzer's results: the peak frequency in Hz, its
 * level in dBm,.
 * Wire: w\r\n
 */
int owlv_wireless_radio_spectrum(int session, int* peak_freq_hz,
                                 int* peak_rssi, unsigned char* bins,
                                 int bins_cap, int* bins_len);

/* Squelch. Sets the level a capture must see before it starts recording, and
 * below.
 * Wire: w\r\u
 */
int owlv_wireless_radio_squelch(int session, int dbm);

/* Replay Invert. Flips the captured low/high phase before re-keying it on
 * Replay..
 * Wire: w\r\v
 */
int owlv_wireless_radio_replay_invert(int session, int on);

/* Transmit Sub. Transmits a Flipper .sub file from the card..
 * Wire: w\r\m
 */
int owlv_wireless_radio_transmit_sub_file(int session, const char* path);

/* Monitor. Keeps the receiver open and samples signal strength continuously,
 * so.
 * Wire: w\r\l
 */
int owlv_wireless_radio_monitor(int session, int on);

/* Enable Reader. Start or stop the 125 kHz carrier and tag reader.
 * Wire: w\p\r
 */
int owlv_wireless_rfid_enable_reader(int session, int enable);

/* Get Status. Reader state, carrier frequency and live envelope.
 * Wire: w\p\g
 */
int owlv_wireless_rfid_get_status(int session, int* state,
                                  unsigned char* flags, int* carrier_hz,
                                  int* env_min, int* env_max, int* threshold,
                                  int* frames, int* tags);

/* Read Tag. Block until one tag is decoded or the timeout expires.
 * Wire: w\p\t
 */
int owlv_wireless_rfid_read_tag(int session, int timeout_ms, int* format,
                                int* modulation, unsigned char* id,
                                int id_cap, int* id_len);

/* Stream Tags. Push each decoded tag to the host as an event.
 * Wire: w\p\s
 */
int owlv_wireless_rfid_stream_tags(int session, int enable);

/* Clear Stats. Zero the frame and tag counters.
 * Wire: w\p\c
 */
int owlv_wireless_rfid_clear_stats(int session);

/* Tune Constant. Set a demodulator constant live, without reflashing.
 * Wire: w\p\u
 */
int owlv_wireless_rfid_tune(int session, int param, int value, int* param_out,
                            int* value_out);

/* Raw Bits. Raw bits of the last assembled frame.
 * Wire: w\p\b
 */
int owlv_wireless_rfid_raw_bits(int session, int* modulation, int* length,
                                unsigned char* bits, int bits_cap,
                                int* bits_len);

/* Write Tag. Write one 32-bit block to a T5577/T5557 tag.
 * Wire: w\p\w
 */
int owlv_wireless_rfid_write_tag(int session, int block, unsigned int value,
                                 int* result, int* block_out);

/* Carrier Info. Measured carrier and PSK front-end telemetry.
 * Wire: w\p\i
 */
int owlv_wireless_rfid_carrier_info(int session, int* carrier_hz,
                                    int* psk_active, int* psk_events,
                                    int* poll_count, int* clk_hz,
                                    int* clock_ok, int* env_samples,
                                    int* overruns, int* restarts,
                                    int* psk_period);

/* Enroll ID. Write a caller-supplied EM4100 ID onto the card in the field.
 * Wire: w\p\n
 */
int owlv_wireless_rfid_enroll_id(int session, const unsigned char* id,
                                 int id_len);

/* Clone Capture. Read a card and hold its ID for a later clone write.
 * Wire: w\p\k
 */
int owlv_wireless_rfid_clone_capture(int session, int timeout_ms);

/* Clone Write. Write the captured ID onto the card now on the coil.
 * Wire: w\p\j
 */
int owlv_wireless_rfid_clone_write(int session);

/* Launch Script. Not yet implemented; always reports failure.
 * Wire: s\a
 */
int owlv_scripting_launch_script(int session);

/* Power Cycle Debugger. Powers debugger zone 16 off for 500 ms, then powers
 * it back on..
 * Wire: s\c
 */
int owlv_scripting_power_cycle_debugger(int session);

/* Add. Adds an app signal..
 * Wire: s\i\a
 */
int owlv_scripting_app_signals_app_signal_add(int session, const char* name);

/* Remove. Removes an app signal..
 * Wire: s\i\x
 */
int owlv_scripting_app_signals_app_signal_remove(int session, const char* name);

/* Rename. Renames an app signal..
 * Wire: s\i\r
 */
int owlv_scripting_app_signals_app_signal_rename(int session,
                                                 const char* name,
                                                 const char* new_name);

/* Set Value. Sets an app signal value..
 * Wire: s\i\s
 */
int owlv_scripting_app_signals_app_signal_set(int session, const char* name,
                                              double value);

/* Get Value. Gets an app signal value..
 * Wire: s\i\g
 */
int owlv_scripting_app_signals_app_signal_get(int session, const char* name,
                                              char* name_out,
                                              int name_out_cap, double* value);

/* Apply Wave. Applies wave mode 0-8 (0 off; sine, triangle, square and saw
 * at 0.5/2 Hz)..
 * Wire: s\i\w
 */
int owlv_scripting_app_signals_app_signal_wave(int session, const char* name,
                                               int wave);

/* Stream. Streams every defined app signal; 0 disables streaming..
 * Wire: s\i\t
 */
int owlv_scripting_app_signals_app_signal_stream(int session,
                                                 int stream_rate_ms);

/* Load. Loads a .wili project..
 * Wire: s\f\l
 */
int owlv_scripting_wili_files_wili_load(int session, const char* filepath);

/* Save Current. Saves the current Wili project to its source path..
 * Wire: s\f\s
 */
int owlv_scripting_wili_files_wili_save(int session);

/* Reset. Clears the live panels, Wili Blocks, and app signals..
 * Wire: s\f\r
 */
int owlv_scripting_wili_files_wili_reset(int session);

/* Make Default. Sets the Wili project loaded at boot..
 * Wire: s\f\m
 */
int owlv_scripting_wili_files_wili_default(int session, const char* filepath);

/* Remove Default. Removes the configured boot Wili project..
 * Wire: s\f\x
 */
int owlv_scripting_wili_files_wili_remove_default(int session);

/* Stream ZoomIO Data. Enables or disables streaming of ZoomIO receive data
 * to the host..
 * Wire: s\b\o
 */
int owlv_scripting_zoom_io_enable_rx_stream(int session, int enable);

/* Write to FIFO. Sends a single ZoomIO message after the given delay (us)..
 * Wire: s\b\w
 */
int owlv_scripting_zoom_io_send_data(int session, int delay,
                                     const unsigned char* data, int data_len);

/* Update Schedule Table. Updates a schedule-table transmit message..
 * Wire: s\b\u
 */
int owlv_scripting_zoom_io_update_table_data(int session, int table_index,
                                             int delay,
                                             const unsigned char* data,
                                             int data_len);

/* Setup Schedule Table. Sets up the schedule table size (0 to disable)..
 * Wire: s\b\p
 */
int owlv_scripting_zoom_io_enable_schedule_table(int session,
                                                 int number_of_entries);

/* Compile test. Compiles built-in ZoomIO milestone program and launches it
 * on core1 as RISC-V.
 * Wire: s\b\c
 */
int owlv_scripting_zoom_io_compile_test(int session);

/* Run ZoomIO. Compile and run a ZoomIO program on the RISC-V core1.
 * Wire: s\b\r
 */
int owlv_scripting_zoom_io_run_zio(int session, const char* path);

/* Stop ZoomIO. Reset core1 to stop the running program.
 * Wire: s\b\s
 */
int owlv_scripting_zoom_io_stop_zio(int session);

/* WASM Debug Start. Loads a .wilwasm for debugging..
 * Wire: s\w\c
 */
int owlv_scripting_wasm_debug_debug_start(int session, const char* path);

/* WASM Debug Breakpoints. Replaces the byte-PC breakpoint set..
 * Wire: s\w\j
 */
int owlv_scripting_wasm_debug_debug_breakpoints(int session, const char* pcs);

/* WASM Debug Step. Steps one opcode, or until the PC leaves [lo,hi)..
 * Wire: s\w\e
 */
int owlv_scripting_wasm_debug_debug_step(int session, const char* range);

/* WASM Debug Continue. Resumes until the next breakpoint..
 * Wire: s\w\f
 */
int owlv_scripting_wasm_debug_debug_continue(int session);

/* WASM Debug Pause. Pauses at the next opcode..
 * Wire: s\w\g
 */
int owlv_scripting_wasm_debug_debug_pause(int session);

/* WASM Debug Stop. Stops the active wasm debug session..
 * Wire: s\w\t
 */
int owlv_scripting_wasm_debug_debug_stop(int session);

/* WASM Debug Locals. Dumps stack frames and raw frame-0 locals..
 * Wire: s\w\i
 */
int owlv_scripting_wasm_debug_debug_locals(int session);

/* WASM Debug Memory Read. Reads up to 64 bytes of wasm linear memory (hex)..
 * Wire: s\w\r
 */
int owlv_scripting_wasm_debug_debug_mem_read(int session, const char* addr);

/* Debug Start. Loads and compiles a script for debugging..
 * Wire: s\r\c
 */
int owlv_scripting_rthon_debug_debug_start(int session, const char* path);

/* Debug Breakpoints. Replaces the breakpoint set for the active debug
 * session..
 * Wire: s\r\j
 */
int owlv_scripting_rthon_debug_debug_breakpoints(int session,
                                                 const char* lines);

/* Debug Step. Single-steps the active debug session..
 * Wire: s\r\e
 */
int owlv_scripting_rthon_debug_debug_step(int session);

/* Debug Continue. Resumes the active debug session until the next
 * breakpoint..
 * Wire: s\r\f
 */
int owlv_scripting_rthon_debug_debug_continue(int session);

/* Debug Pause. Pauses the active debug session at the next statement..
 * Wire: s\r\g
 */
int owlv_scripting_rthon_debug_debug_pause(int session);

/* Debug Stop. Stops the active debug session..
 * Wire: s\r\t
 */
int owlv_scripting_rthon_debug_debug_stop(int session);

/* Debug Locals. Dumps the local variables of the active debug session..
 * Wire: s\r\i
 */
int owlv_scripting_rthon_debug_debug_locals(int session);

/* Launch App. Switch the built-in display to the app with the given app ID.
 * Wire: a\a
 */
int owlv_apps_launch_app(int session, int app_id);

/* Run App. Runs /apps/<filename> on the display processor. The destination
 * is inferred by reading the image, not the name: a UF2 whose blocks target
 * SRAM is staged in RAM and launched; one targeting the PSRAM window
 * (0x11000000) is staged into PSRAM through the loader stub and launched;
 * anything else is written to flash. RAM and PSRAM launches leave flash
 * untouched. A flash load takes 30-60 seconds with the screen blank..
 * Wire: a\r
 */
int owlv_apps_run_app(int session, const char* filename);

/* Enable Linux CPU. Not yet implemented; always reports failure.
 * Wire: l\a
 */
int owlv_linux_enable_linux_cpu(int session);

/* Open Shell.
 * Wire: l\b
 */
int owlv_linux_open_shell(int session);

/* Start. Arms the logger with the current settings; Immediate trigger mode
 * starts capturing at once. Emits logger events
 * (armed/triggered/complete/error) as it runs..
 * Wire: r\s
 */
int owlv_logger_start(int session);

/* Stop. Stops the logger: an armed capture is discarded, a running capture
 * drains its remaining events to the files and closes them..
 * Wire: r\e
 */
int owlv_logger_stop(int session);

/* Trigger. Software trigger: fires an armed capture regardless of the
 * configured trigger mode..
 * Wire: r\t
 */
int owlv_logger_trigger(int session);

/* Status. Prints the logger state, file format, trigger mode, output file
 * names and event counters..
 * Wire: r\i
 */
int owlv_logger_status(int session);

/* File Format. Output file format for the next capture: CSV text, RTIX
 * binary, or both.
 * Wire: r\f
 */
int owlv_logger_file_format(int session, int value);

/* Trigger Mode. How an armed capture is triggered: Immediate (on start),
 * Button (a device button press), or Expression (a device expression
 * becoming nonzero).
 * Wire: r\m
 */
int owlv_logger_trigger_mode(int session, int value);

/* Trigger Button. Device button that fires the trigger in Button mode.
 * Wire: r\b
 */
int owlv_logger_trigger_button(int session, int value);

/* Trigger Expression. Expression evaluated every 50 ms in Expression mode;
 * the trigger fires when it evaluates nonzero.
 * Wire: r\x
 */
int owlv_logger_trigger_expression(int session, const char* value);

/* Pre Trigger Ms. Milliseconds of events kept from before the trigger
 * (0-60000).
 * Wire: r\p
 */
int owlv_logger_pre_trigger_ms(int session, int value);

/* Post Trigger Ms. Milliseconds captured after the trigger before the files
 * close (0 = until stop, max 600000).
 * Wire: r\o
 */
int owlv_logger_post_trigger_ms(int session, int value);

/* Events. Selects which events this instance captures: "all", "none", a
 * comma-separated event-name list, or +name/-name to add/remove one event
 * from the current selection.
 * Wire: r\v
 */
int owlv_logger_events(int session, const char* value);

/* Active Instance. Selects which of the four logger instances (0-3) the
 * settings rows show and the start, stop and trigger commands act on; every
 * instance keeps its own saved configuration.
 * Wire: r\n
 */
int owlv_logger_active_instance(int session, int value);

/* Name. Optional name for this instance; captures are written to
 * /logs/<name>/<name>_NNNN.* instead of /logs/logI_NNNN.*.
 * Wire: r\a
 */
int owlv_logger_name(int session, const char* value);

#endif /* ONEWILI_LV_API_H */
